// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    address keeper = address(0x1234);

    function setUp() public {
        c = new DnGmxBatchingManager();
        MockERC20 sGlp = new MockERC20();
        MockERC20 usdc = new MockERC20();
        MockRewardRouter router = new MockRewardRouter();
        MockGlpManager gm = new MockGlpManager();
        c.initialize(
            IERC20(address(sGlp)),
            IERC20(address(usdc)),
            IRewardRouterV2(address(router)),
            IGlpManager(address(gm)),
            address(0x5678),
            keeper
        );
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != keeper && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, type(uint128).max);

        // fund the current round via depositUsdc from this (unpaused, ungated)
        c.depositUsdc(amount, address(this));

        // satisfy the 15-minute cooldown of executeBatchDeposit
        vm.warp(block.timestamp + 1 hours);

        vm.prank(actor);
        try c.executeBatchDeposit() {
            // non-keeper must never be able to execute a batch deposit
            assertTrue(false, "non-keeper executed batch deposit");
        } catch {
            // reference path: the call reverts and batching state is untouched
        }

        // The current round must never advance for a non-keeper caller
        assertTrue(c.currentRound() == 1, "round advanced for non-keeper");
    }
}

contract MockERC20 {
    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

contract MockRewardRouter {
    function mintAndStakeGlp(address, uint256, uint256, uint256) external pure returns (uint256) {
        return 0;
    }
}

contract MockGlpManager {
    function vault() external pure returns (address) {
        return address(0x9999);
    }
}
